import fs from 'fs';
import path from 'path';
import { uploadDirectory } from '../../db/location';

// Where uploaded files live. The default adapter keeps them on the server's disk, in UPLOAD_DIR (default: an
// "uploads" folder next to the database file, so tests and each environment keep their own). Keys are generated by
// the server (organization id / random id . extension); a key that would leave the folder is refused. Another adapter
// (for example object storage) can implement the same interface; none is configured in this version.

export interface MediaStorage {
  readonly name: string;
  put(key: string, bytes: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  remove(key: string): Promise<void>;
}

const KEY = /^[A-Za-z0-9_-]{1,64}\/[A-Za-z0-9_-]{8,64}\.(png|jpg|webp)$/;

export function isStorageKey(key: string): boolean {
  return KEY.test(key);
}

export class LocalDiskStorage implements MediaStorage {
  readonly name = 'local-disk';
  constructor(private readonly root: string) {}

  private file(key: string): string {
    if (!isStorageKey(key)) throw new Error('Invalid storage key');
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, bytes: Buffer): Promise<void> {
    const file = this.file(key);
    await fs.promises.mkdir(path.dirname(file), { recursive: true });
    // Written to a temporary name first, so a reader never sees half a file.
    const tmp = `${file}.${process.pid}.tmp`;
    await fs.promises.writeFile(tmp, bytes, { flag: 'wx' });
    await fs.promises.rename(tmp, file);
  }

  async get(key: string): Promise<Buffer | null> {
    try { return await fs.promises.readFile(this.file(key)); } catch (e) {
      if ((e as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw e;
    }
  }

  async remove(key: string): Promise<void> {
    await fs.promises.rm(this.file(key), { force: true });
  }
}

let current: MediaStorage | null = null;

/** The configured storage: UPLOAD_DIR, or "uploads" beside the database. */
export function mediaStorage(): MediaStorage {
  if (!current) {
    current = new LocalDiskStorage(uploadDirectory());
  }
  return current;
}

/** For tests: use another storage (for example one that fails). */
export function setMediaStorage(storage: MediaStorage | null): void {
  current = storage;
}
